// USDA-derived foods (auto-generated by the pipeline) supply everything
// outside spices/fermented. Apply BLS price overrides on top — each entry in
// BLS_OVERRIDES[id] is a partial price record; the spread merges so regions
// absent from the BLS data fall back to the baseline values.
const ALL_FOODS = [...FOODS_BASE, ...USDA_FOODS];
export const FOODS = ALL_FOODS.map(f => {
  const override = BLS_OVERRIDES[f.id];
  if (!override) return f;
  return { ...f, price: { ...f.price, ...override } };
});

// Region labels for the pricing keys
export const REGIONS = {
  us: 'US Average',
  ne: 'Northeast',
  mw: 'Midwest',
  so: 'South',
  we: 'West',
};
